def linear_steps(items, target):
    steps = 0
    for x in items:
        steps += 1
        if x == target:
            break
    return steps

print(linear_steps(list(range(1000)), 999))

def binary_steps(items, target):
    lo, hi, steps = 0, len(items) - 1, 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if items[mid] == target:
            return steps
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps

print(binary_steps(list(range(1000)), 999))

